function go(p){page=p;render();window.scrollTo(0,0);}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
function lessonRows(all=false){return titles.slice(0,all?6:4).map((t,i)=>`<div class="lesson ${state.done.includes(i)?'done':i==nextLesson()?'current':'pending'}"><span class="lesson-num">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${t}</strong><small>${['Discover · 4 min','Rhythm · 3 min','Listening · 4 min','Notation · 4 min','At-home practice · 3 min','Independent check · 5 min'][i]}</small></div><button data-lesson="${i}" aria-label="Open ${t}">${state.done.includes(i)?'Review ↗':i===nextLesson()?'Begin →':'Explore ↗'}</button></div>`).join('');}
function nextLesson(){return titles.findIndex((_,i)=>!state.done.includes(i))<0?5:titles.findIndex((_,i)=>!state.done.includes(i));}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#goalText').textContent=state.goal+' min / day';$('#crumb').innerHTML='Your learning / <b>'+({home:'Overview',practice:'Practice studio',progress:'My progress',schools:'Beyond the screen',path:'Violin foundations'}[page])+'</b>';
if(page==='home'){main.innerHTML=`<div class="welcome"><div><div class="eyebrow">A LITTLE PRACTICE. A LIFELONG POSSIBILITY.</div><h1>Your musical beginning.</h1><p class="sub">No perfect timing. No expensive setup. Just you, starting.</p></div><span class="datepill">✧ Your pace. Your possibility.</span></div><section class="hero"><div class="hero-copy"><span class="tag">YOUR FIRST CHAPTER</span><h2>There’s a musician<br>in you. Let’s begin.</h2><p>Get to know the violin, find your rhythm, and build a foundation. One small step at a time.</p><button class="primary" data-lesson="${nextLesson()}">${state.done.length?'Continue learning':'Start my first lesson'} <span>→</span></button><small>✧ No instrument needed</small></div><div class="hero-art">${violin}<span class="art-label">THE VIOLIN · YOUR FIRST POSSIBILITY</span></div></section><div class="two-col"><section><div class="sectionline"><h2>Your learning path</h2><button class="link" id="viewPath">View full path ↗</button></div><div class="card path"><div class="path-head"><div class="iconbox">♮</div><div><h3>Violin foundations</h3><small>Chapter 01 · Start with the essentials</small></div><span class="badge">${state.done.length} / 6 complete</span></div>${lessonRows()}</div></section><section><div class="sectionline"><h2>Start with what you have</h2></div><div class="card kit"><div class="eyebrow">THE AT-HOME PRACTICE KIT</div><h2>Ordinary objects.<br>Extraordinary beginnings.</h2><p>Your tabletop, your hands, a little curiosity.<br>Your first practice kit is already at home.</p><div class="kit-art"><div class="pencil"></div><span class="hand">⌁</span></div><button id="kit">Explore my practice kit ↗</button></div></section></div><section class="instrument-section"><div class="sectionline"><h2>One beginning. Many possibilities.</h2><span class="eyebrow" style="font-size:8px">FIND YOUR INSTRUMENT</span></div><div class="instruments">${[['🎻','Violin'],['🎹','Piano'],['🎸','Guitar'],['🥁','Drums'],['🪈','Flute'],['🎷','Saxophone']].map(([em,n],i)=>`<button class="instrument ${i===0?'selected':''}" data-instrument="${n}">${i===0?'<span class="dot">●</span>':''}<span class="emoji">${em}</span><strong>${n}</strong><small>${i===0?'Your active pathway':'Coming in a future chapter'}</small></button>`).join('')}</div></section><div class="bottom-note"><span class="seed">♧</span><div><strong>From your room to a real music room.</strong><p>Our vision: turn your foundations into a first experience at a music school.</p></div><button class="link" id="beyond">Meet the possibility ↗</button></div>`;$('#viewPath').onclick=()=>go('path');$('#kit').onclick=kit;$('#beyond').onclick=()=>go('schools');document.querySelectorAll('[data-instrument]').forEach(b=>b.onclick=()=>b.dataset.instrument==='Violin'?go('path'):open(`<div class="eyebrow">A FUTURE CHAPTER</div><h2>${b.dataset.instrument}</h2><p class="modal-sub">This pathway is planned. Violin foundations is the first working pathway, so we can learn what helps before expanding.</p><button class="primary" id="tryViolin">Explore violin foundations →</button>`)||null);}
if(page==='path'){main.innerHTML=`<div class="eyebrow">YOUR CURRICULUM · CHAPTER 01</div><h1>Violin foundations.</h1><p class="sub">Build knowledge, listening, rhythm, and coordination from scratch.</p><div class="card full-path">${lessonRows(true)}</div><p class="fine">Explore lessons in any order. Completion reflects in-app checks, not a certification of physical violin technique.<br>This prototype curriculum needs review by a qualified violin teacher before instructional release.</p>`;}
if(page==='practice'){main.innerHTML=`<div class="eyebrow">LISTEN. EXPLORE. REPEAT.</div><h1>Your practice studio.</h1><p class="sub">Small exercises. Real attention. Come back to what needs a little care.</p><div class="practice-grid">${[['♬','Open-string sound lab','Explore G, D, A, and E with synthesized reference tones.','strings'],['◴','Find your pulse','Hear a steady beat, then try keeping it on your own.','rhythm'],['♮','Train your ear','Compare two pitches. Can you hear which is higher?','ear'],['⌁','Away from the screen','Practice finger independence with your hands and a tabletop.','kit']].map(([i,t,d,a])=>`<div class="card practice-card"><span class="practice-icon">${i}</span><h2>${t}</h2><p>${d}</p><button class="secondary" data-action="${a}">Open exercise →</button></div>`).join('')}</div>`;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>({strings:strings,rhythm:rhythm,ear:ear,kit:kit}[b.dataset.action])());}
if(page==='progress'){const avg=state.attempts.length?Math.round(state.attempts.reduce((s,a)=>s+a.score,0)/state.attempts.length):0;main.innerHTML=`<div class="eyebrow">YOUR EFFORT, MADE VISIBLE</div><h1>Every beginning counts.</h1><p class="sub">An honest picture of what you’ve practiced and demonstrated.</p><div class="stat-grid"><div class="card stat"><span class="eyebrow">MILESTONES</span><div class="big-number">${state.done.length}<span style="font-size:23px;color:#aa8eac"> / 6</span></div><p>Foundation lessons completed</p></div><div class="card stat"><span class="eyebrow">RHYTHM CHECKS</span><div class="big-number">${state.attempts.length}</div><p>${state.attempts.length?'Average timing score: '+avg+'%':'Your first rhythm check is waiting'}</p></div><div class="card stat"><span class="eyebrow">DAILY INTENTION</span><div class="big-number">${state.goal}<span style="font-size:20px"> min</span></div><p>A goal, without the guilt</p></div></div><div class="card path"><h2>Your foundation record</h2><div class="meter"><i style="width:${state.done.length/6*100}%"></i></div>${lessonRows(true)}</div><div class="bottom-note"><span class="seed">♧</span><div><strong>Your first real-instrument assessment is still ahead.</strong><p>Screen exercises and self-reported movements do not verify posture, bow control, or string pressure.</p></div></div><div class="modal-actions"><button class="secondary" id="export">Export my progress</button><button class="link" id="reset">Reset this device’s progress</button></div>`;$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({app:'Arco',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='arco-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#reset').onclick=()=>{open('<h2>Begin a fresh chapter?</h2><p class="modal-sub">This removes completed lessons and rhythm records from this browser. Export your progress first if you want to keep it.</p><button class="secondary" id="confirmReset">Reset my progress</button>');$('#confirmReset').onclick=()=>{state={done:[],goal:10,attempts:[],kit:false};save();close();render();};};}
if(page==='schools'){main.innerHTML=`<div class="eyebrow">BEYOND THE SCREEN</div><h1>Your first real music room.</h1><p class="sub">Learning should open doors. This is the door we want to build.</p><section class="hero" style="margin-top:27px"><div class="hero-copy"><span class="tag">OUR FUTURE SCHOOL PILOT</span><h2>From “one day”<br>to your first day.</h2><p>A proposed free introductory week with a music school, giving learners a chance to try a real instrument and receive personal guidance.</p><button class="primary" id="pilot">How the pilot would work →</button></div><div class="hero-art">${violin}</div></section><div class="practice-grid"><div class="card practice-card"><span class="eyebrow">01 · BUILD YOUR FOUNDATION</span><h2 style="margin-top:14px">Show up for yourself.</h2><p>Build a record of your listening, rhythm, and musical understanding. Access barriers and improvement would matter alongside consistency.</p></div><div class="card practice-card"><span class="eyebrow">02 · PUT IT INTO PRACTICE</span><h2 style="margin-top:14px">Meet an instrument. And a teacher.</h2><p>Our proposed pilot would invite three learners to explore an instrument, receive an assessment, and take an introductory course week.</p></div></div><p class="fine">Planning stage: no schools, free places, dates, or selection process have been confirmed. This page explains the vision; it does not accept applications.</p>`;$('#pilot').onclick=()=>open('<div class="eyebrow">THE PROPOSED PILOT</div><h2>A bridge into music.</h2><p class="modal-sub">1. Complete a beginner foundation pathway.<br><br>2. Demonstrate independent knowledge and consistent practice.<br><br>3. When a school partnership is secured, publish eligibility and a fair selection process for three free introductory places.<br><br>4. Learn with a teacher and assess which skills transferred to a real instrument.</p><p class="fine">This is a proposed program, not an available award. No application is being collected.</p>');}
document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>lesson(Number(b.dataset.lesson)));}
